  const lastSlashIndex = normalizedPath.lastIndexOf('/');

  if (lastSlashIndex === -1) {
    return normalizedPath;
  }

  return normalizedPath.slice(lastSlashIndex + 1);
}

function acceptsOptionValue(token) {
  if (token === undefined || token === '--') {
    return false;
  }

  return !token.startsWith('-') || token === '-' || NEGATIVE_NUMBER_LIKE.test(token);
}

export function getProgramName(argv = process.argv) {
  const programName = basename(Array.isArray(argv) ? argv[1] : '');
  return programName || 'test7.mjs';
}

export function formatUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

export function formatHelp(programName) {
  return `${formatUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n`;
}

function formatError(programName, message) {
  return `${formatUsage(programName)}\n${programName}: error: ${message}\n`;
}

export function parseTest7Arguments(argv = process.argv) {
  const programName = getProgramName(argv);
  const tokens = Array.isArray(argv) ? argv.slice(2) : [];
  let aValue;
  let bValue;
  const extras = [];

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (token === '-h' || token === '--help') {
      return {
        exitCode: 0,
        kind: 'help',
        text: formatHelp(programName),
      };
    }

    if (token === '--') {
      extras.push(...tokens.slice(index + 1));
      break;
    }

    if (token === '--a' || token === '--b') {
      const nextToken = tokens[index + 1];

      if (!acceptsOptionValue(nextToken)) {
        return {
          exitCode: 2,
          kind: 'error',
          text: formatError(programName, `argument ${token}: expected one argument`),
        };
