        aValue = nextToken;
      } else {
        bValue = nextToken;
      }

      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      aValue = token.slice(4);
      continue;
    }

    if (token.startsWith('--b=')) {
      bValue = token.slice(4);
      continue;
    }

    extras.push(token);
  }

  if (extras.length > 0) {
