    return {
      exitCode: 2,
      kind: 'error',
      text: formatError(
        programName,
        `the following arguments are required: ${missing.join(', ')}`,
      ),
    };
  }

  return {
    exitCode: 0,
    kind: 'ok',
    values: {
      a: aValue,
      b: bValue,
    },
  };
}

